import { ImageResponse } from "next/og";

// Dynamic PWA icon generated by Next.js on first request + cached at the
// edge. Used by browsers for favicon + PWA manifest. Updating this file
// invalidates the cache so logo tweaks ship on next deploy with no asset
// shuffling.

export const size = { width: 192, height: 192 };
export const contentType = "image/png";

export default function Icon() {
  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          background:
            "linear-gradient(135deg, #064e3b 0%, #022c22 50%, #000000 100%)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "#6ee7b7",
          fontSize: 110,
          fontWeight: 800,
          fontFamily: "system-ui, -apple-system, Helvetica, Arial, sans-serif",
          letterSpacing: "-2px",
        }}
      >
        ⭐
      </div>
    ),
    { ...size },
  );
}
